from math import comb

def count_tours(k, l, r):
    if k > 4:
        return 0

    mod = 10**9 + 7
    total_tours = 22 - k - k * (k - 1) // 2

    if l == 1:
        l = 0
    elif r == 1:
        r = 0

    if k == 1:
        if l == r:
            return 1
        elif l < r:
            return comb(r + k - 1, k) % mod
        else:
            return 0

    if k == 2:
        if l == r:
            return 0
        elif l+r < k-1:
            return 0
        elif l == r:
            return 1
        return comb(r-l, k) % mod
    else:
        return (comb(r, k) * ((k+1) ** 2 + (k-1) ** 2 - 2k ** 2) // (2*k) % mod) % mod

