def is_connected(edges):
    adjacency_list = [[] for _ in range(n)]
    for edge in edges:
        adjacency_list[edge[0]].append(edge[1])
        adjacency_list[edge[1]].append(edge[0])

    connected = [0] * n
    visited = [False] * n

    def dfs(node):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in adjacency_list[node]:
            dfs(neighbor)

    for i in range(n):
        if not visited[i]:
            dfs(i)

    return all(visited)

# Function to calculate the average danger
def calculate_average_danger(edges):
    if not is_connected(edges):
        return -1  # Not a connected graph, we can't proceed

