import sys
from typing import List

def solve_queries(EC: int, queries: List[List[int]]) -> List[float]:
    # Add event to limits array
    eventLimits = []
    for query in queries:
        if query[0] == 1:
            eventLimits.append((query[1], query[2]))
        elif query[0] == 2:
            updateEventLimits(eventLimits, query[1])
        elif query[0] == 3:
            burstTime = simulateJumpingBowl(eventLimits, query[1])
            if burstTime != -1:
                eventLimits.clear()  # Remove all event limits for this query
            if burstTime == 0:
                eventLimits.clear()  # Remove empty event limits array
    return [time for _, time in eventLimits if time > 0]

def updateEventLimits(eventLimits, second):
    for t, s in reversed(eventLimits):
        if t <= second:
            break
        else:
            eventLimits.pop()
    eventLimits.append((second, s))

def simulateJumpingBowl(eventLimits, limitSecondAt):
    totalAbsorbed = 0
    currentEvent = [0, 0]
    for t, s in reversed(eventLimits):
        totalAbsorbed += t * s
        if t < limitSecondAt:
            time = 2 * limitSecondAt - t - 1
            if totalAbsorbed >= time:
                return float('-inf')  # Bowl bursts
        else:
            break
        currentEvent = (currentEvent[0] + s, currentEvent[1] + abs(t - currentEvent[0]) / s)

    return currentEvent[0]

