from heapq import heappush, heappop

def expected_value(n, r, initial_values, changes):
    result = [0.0] * (1 + r)
    elements = []
    heappush(elements, (-result[0], 0, 0, initial_values[0]))

    for i in range(1, len(result)):
        _, idx, _, curr_value = heappop(elements)
        new_values = list(initial_values)
        new_values[idx] = (curr_value - idx) * (1 - 2 * i / (2**n))
        result[i] = final_value_on_right(result[i-1], changes, new_values)
        for j in range(1, len(new_values), 2):
            new_values[j] = (new_values[j] - j) * (1 - 2 * (i - j + 1) / (2**n))
            new_values[j] += 1
            new_values[j] *= 2
            new_values[j-1] = (new_values[j-1] - j) * (1 - 2 * (i - j + 1) / (2**n))
            if (j + 1) < len(new_values):
                new_values[j+1] = (new_values[j+1] - j - 1) * (1 - 2 * (i - j + 1) / (2**n))
            heappush(elements, (-result[i], j, new_values[-1], new_values.pop()))
        heappush(elements, (-result[i], 2**n-1, 2**n-1, new_values[-1]))

    if r > 0:
        heappush(elements, (-result[r], -2**n, -2**n, -initial_values[-1] + sum([2 * _i / (2**n) for _i in range(1, 2**n + 1)])))

    for i in range(len(result)):
        result[i] = final_value_on_right(result[i], changes, initial_values + ([0] * (len(result) - i) * 2 if i < len(changes) else initial_values))

    return result

def final_value_on_right(val, changes, new_values):
    change_value = 0
    shift = 0
    for i, v in enumerate(changes):
        if i < len(new_values):
            change_value += v * ((2**n - 1 - i + n) >> shift) * 2
        else:
            change_value += v * (2**n >> shift) * 2
        shift += 1
    if (new_values[-1] - change_value) == 0:
        return val
    if (new_values[-1] - change_value) % 2 == 0:
        if (new_values[-1] - change_value) % 4 == 0:
            return val + (-new_values[-1] + change_value) / 2
        else:
            return (val + (-new_values[-1] + change_value) / 4 + 2) / 2
    else:
        return final_value_on_right(val, changes, [new_values[-1]]) + (-new_values[-1] + change_value) / 2

n, r = map(int, input().split())
initial_values = list(map(int, input().split()))
changes = [list(map(int, input().split())) for _ in range(r)]
