    total_a = 0
    total_b = 0
    for cell in path:
        total_a += table[cell[0]][cell[1]].count('a')
        total_b += table[cell[0]][cell[1]].count('b')
    return total_a == total_b

def simulate_game(table):
    path_counts = [[0 for _ in range(len(table))] for _ in range(2)]
    for path in paths(table):
        if is_good_path(path, table):
            if path[-1][-1] == 'a':
                path_counts[path[-1][-2]] += 1
            else:
                path_counts[path[-1][-2] + 1] += 1
    if path_counts[0] == path_counts[1]:
        return "DRAW"
    else:
        return "FIRST" if path_counts[0] > path_counts[1] else "SECOND"

def paths(table):
    if not table or not table[0]:
        return []
    n = len(table)
