            while (i + path[-1][0] >= 1 and j + path[-1][1] >= 1 and table[i][j].count('a') <= table[i][j].count('b')):
                path.append((i + path[-1][0], j + path[-1][1]))
            paths.append(path[::-1])
    return paths

