def max_score(A, Q, queries):
    A.sort(reverse=True)
    score = 0
    best_score = 0
    for q in queries:
        first, second = A[0], A[1]
        third, fourth = A[2], A[3]
        if q == 1 or q == 4:
            first, second = second, first
        if q == 2 or q == 3:
            third, fourth = fourth, third
        if q == 1:
            best_score += (first - second)
        else:
            best_score -= (first - second)
        for i in range(0, len(A) // 2 * 2, 2):
            if A[i] > A[i + 1]:
                A[i], A[i + 1] = A[i + 1], A[i]
        best_score += (A[-1] + A[-2] - (A[0] + A[1]))
