from collections import defaultdict

def count_ways(k, l, r):
    modulo = 1000000007
    dp = [0] * (k + 1)
    dp[0] = 1  # Base case: there's one way to do nothing (select 0 tours of any length)

    for i in range(l, r + 1):
        new_dp = [0] * (k + 1)
        for j in range(k):
            for m in range(j, i + 1):
                j += dp[j]
            if i - k + j > 0:
                for m in range((i - k + j) // j, i + 1):
                    j += dp[j]
            new_dp[j] = dp[j]
            dp[j] = 0
            for d in range(j + 1, i + 1):
                new_dp[d] = (new_dp[d - j] if d - j > 0 else 0) + dp[d]
        if i - k + 1 > 0:
            for d in range(i - k + 1, r + 1):
                new_dp[d] = (new_dp[d - j] if d - j > 0 else 0) + dp[d]
        dp = new_dp
    return sum(dp) % modulo

