import itertools

def is_good_string(s):
    # Count the number of 'a' and 'b' in the string
    if s.count('a') > s.count('b'):
        return "FIRST"
    elif s.count('a') < s.count('b'):
        return "SECOND"
    else:
        return "DRAW"

def solve(table):
    rows, cols = len(table), len(table[0])
    n = rows

    if n % 2 == 0:
        return "DRAW"

    unique_strings = [''.join(s) for s in itertools.product('ab', repeat=n)]

    good_paths = set()

    for path in unique_strings:
        for i in range(1, n+1):
            if path[:i] in unique_strings:
                good_paths.add(path)

    if len(good_paths) >= 2**n - 1:
        return "MULTIPLE WIN"

    for path in good_paths:
        if is_good_string(path) not in table[n-1]:
            table[n-1].append(is_good_string(path))

    for row in table:
        if 'DRAW' in row:
            return 'MULTIPLE WIN'

    return 'FIRST' if 'FIRST' in table[n-1] else 'SECOND'

