import sys
from collections import defaultdict

def calculate_total_danger(passages):
    total_danger = 0
    for _ in range(n - k):
        silos = []
        s = k
        while s > 0:
            s -= 1
            total_danger += passages[s][k]
            for _ in range(k - 1, 0, -1):
                total_danger += passages[s][_]
                total_danger -= passages[s][_ + 1]
                s += 1
            silos.append(s)
            for _ in range(k - 1):
                s -= 1
                total_danger -= passages[s][k]
                for _ in range(k):
                    total_danger += passages[s][_]
                    total_danger -= passages[s][_ + 1]
                    s += 1
            s = k
        silos_to_remove = []
        while len(silos) > 0:
            current_silo = silos.pop()
            total_danger -= passages[current_silo][k]
            for _ in range(k):
                total_danger += passages[current_silo][_]
                total_danger -= passages[current_silo][_ + 1]
                silos_to_remove.append(current_silo)
            for _ in range(k):
                silos.append(current_silo)
        silos.sort()
        while len(silos_to_remove) > 0:
            total_danger -= passages[silos_to_remove.pop()][k]
    return total_danger

def main(n, k, passages):
    total_dangers = []
    for _ in range(0 if k * (k - 1) < n else n * (n - 1) // 2):
        total_dangers.append(int(sys.stdin.readline().strip()))
    closest_among_total_dangers(total_dangers)
    return calculate_total_danger(passages)

def closest_among_total_dangers(total_dangers):
    total_danger = 0
    for _ in range(k * (n - k)):
        total_danger -= sys.stdin.readline().strip()
    return str(total_danger // (n * n - n))

if __name__ == "__main__":
    n, k = map(int, sys.stdin.readline().strip().split())
    passages = list(map(lambda line: list(map(int, line.split())), sys.stdin.read().strip().split('\n')))
    print(main(n, k, passages))
