import sys

def min_total_distance(photos, special_ones):
    import numpy as np
    np.seterr(divide='ignore', invalid='ignore')
    heights = np.zeros((len(photos), len(photos[0])))
    for i in range(len(photos)):
        row = [int(x) for x in photos[i]]
        heights[i, :len(row)] = row
    photos = heights
    min_distance = float('inf')
    rows, cols = photos.shape
    for start_1 in range(rows):
        for cols in range(start_1, rows):
            sum_ = 0
            distance_required_ = float('inf')
            for start_2 in range(start_1, cols):
                start_3 = min(cols - 1, start_2)
                end_1 = min(pow(-2, start_1 - start_2), start_1)
                end_2 = min(cols - pow(-2, start_2 - start_3), start_2)
                if distance_required_ < sys.maxsize:
                    break
                distance_required_ = min(distance_required_, end_2 - start_3)
                for start_4 in range(start_1, end_2):
                    for start_5 in range(start_2, end_1):
                        d1, d2 = abs(start_4 - start_1), abs(start_5 - start_2)
                        d = d1 + d2
                        sum_ += d
                        if d > distance_required_:
                            break
                    else:
                        continue
                    found_out = True
                    for i, height in enumerate(special_ones):
                        start = heights[i, start_1:start_4]
                        end_1 = heights[i, start_2:end_2]
                        for j in range(height.shape[0]):
                            for k in range(height.shape[1]):
                                flattened_height = np.vstack((start[j, :, np.newaxis], end_1[j, :, np.newaxis]))
                                pointer = flattened_height[j, k, 0]
                                if pointer > rows or pointer < 0 or (k == 0 and flattened_height[0, k] > 0) or (k == flattened_height.shape[1] - 1 and flattened_height[-1, k] > 0):
                                    found_out = False
                                    break
                            if not found_out:
                                break
                        if not found_out:
                            break
                    else:
                        special_ones.insert(i, heights[i, start_1:start_4])
                        found_out = True
                    if not found_out:
                        break
                if not found_out:
                    break
            if not found_out:
                min_distance = min(min_distance, sum_)
            else:
                break
    return min_distance

