def count_good_substrings(s: str, n: int, rules: List[str]) -> int:
    distinct_strings = set()
    dp = [set() for _ in range(len(s) + 1)]
    dp[0].add("")

    for rule in rules:
        p, l, r = rule
        for i in range(len(dp)):
            for j in range(len(p), -1, -1):
                if p[j:j+len(s[i-1])) in dp[i-1]:
                    new_string = dp[i - 1][p[j:j+len(s[i-1])]] + s[i-1]
                    if dp[i].add(new_string) or new_string in distinct_strings:
                        distinct_strings.add(new_string)

    return len(distinct_strings)

