import math

def calculate_average_hazard(n_silos, k_scouts, droids):
    hazards = 0
    total_hazard = 0

    for i in range(n_silos):
        passage_droids = []
        for j in range(i + 1, n_silos + 1):
            if droids[j - 1 - (i + 1)] == -1:
                break
            passage_droids.append(droids[j - 1 - (i + 1)])

        if len(passage_droids) == k_scouts:
            hazards += 1
            hazard = 1
            for droid in passage_droids:
                hazard += 1
                if droid != -1:
                    hazard *= droid
            total_hazard += hazard

    average_hazard = (total_hazard // hazards) if hazards > 0 else 0
    return math.floor(average_hazard)

