def answer_queries(qs):
    ans = []
    for i, query in enumerate(qs):
        if query[0] == 1:
            v = query[2]
            for event in qs[i - 2::-1]:
                if event[1] - 1 == query[1]:
                    v = event[2]
            ans.append(simulate_pumping(v, query[1]))
        elif query[0] == 2:
