class Yanghui:
    def __init__(self, n: int, a: List[int]):
        self.n = n
        self.a = a

    def compute_lcm(self, i: int, j: int) -> int:
        last = i if 0 < i else j
        while (i <= 0 or j <= 0) or (self.a[i] <= self.a[j]):
            if i > 0:
                i -= 1
            else:
                i = self.n + 1
            if j > 0:
                j -= 1
            else:
                j = self.n + 1

        current_lcm = self.a[self.a[i] == self.a[self.n]].lcm(self.a[self.a[j] == self.a[self.n]])
        i = (self.last + i) % self.n + 1
        j = (self.last + j) % self.n + 1
        if i > j:
            i, j = j, i
        return current_lcm

    @property
    def last(self):
        return 0

    @property
    def n(self):
        return len(self.a)

    @property
    def a(self):
        return self._a

    @a.setter
    def a(self, a):
        nl = len(self.a)

        self._a = a
        if nl >= self.n:
            self.n = nl
        self.a[:self.n - 1] = self.a[nl - 1:]
        self.a[nl - 1:] = [0] * (self.n - nl + 1)
