import sys

def build_graph(intersections, roads):
    graph = {i: [] for i in range(1, intersections + 1)}
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def dfs(current, route, graph, visited, intersections):
    if len(route) == 3:
        return
    # To avoid cycles, only add unvisited intersections that are not in the current route
    available_intersections = {i for i in range(1, intersections + 1) if i not in route and i not in visited}
    for next_inter in available_intersections:
        if next_inter not in route:
            dfs(i, route + [next_inter], graph, visited, intersections)

def find_routes(intersections, roads, start, end):
    graph = build_graph(intersections, roads)
    visited = set()
    available_roads = set()
    for i in range(1, intersections + 1):
        visited.add(i)
        for next_inter in graph[i]:
            if not (next_inter == start or next_inter == end):
                available_roads.add((i, next_inter))
        dfs(i, [i], graph, visited, intersections)
        available_roads.pop()
    count = 0
    while len(available_roads) + count < 3:
        dfs(next_inter, [next_inter], graph, visited, intersections)
        count += 1
    return count > 0

